using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "UseEffectAsDescriptionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/UseEffectAsDescriptionCustomDescription", order = 0)]
public class UseEffectAsDescriptionCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private Effect effect;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		int finalAmountWithoutEquation = GetFinalAmountWithoutEquation(amountModified);
		return effect.GetEffectDescription(finalAmountWithoutEquation);
	}
}
